const flow = wizard();
console.log(flow.next().value);      // "name?"
console.log(flow.next("Ada").value); // "hi Ada"`,caption:`Each .next(answer) both answers and asks the next question.`},{kind:`heading`,text:`5. Prime before sending input`},{kind:`paragraph`,text:"The first `.next(value)` is always discarded — call `.next()` once first."},{kind:`playground`,code:`function* echoer() {
